16	package com.android.car.voicecontrol.actuators;
17	
18	import android.content.Context;
19	
20	import com.android.car.voicecontrol.R;
21	import com.android.car.voicecontrol.TextToSpeech;
22	
23	import java.util.ArrayList;
24	import java.util.Arrays;
25	import java.util.List;
26	
27	/**
28	 * Fake implementation NLP and command recognition. This is a very simplified implementation, only
29	 * to illustrate the execution of a limited set of commands with a fixed set of recognized phrases.
30	 */
31	public class SkillRouter {
32	    private static final List<Actuator> ACTUATORS = Arrays.asList(
33	            new NavigationActuator(),
34	            new VoiceActuator(),
35	            new MediaActuator(),
36	            new RadioActuator(),
37	            new CarActuator(),
38	            new CommActuator());
39	    private List<Skill> mSkills = new ArrayList<>();
40	
41	    /**
42	     * An encapsulation of related skills.
43	     */
44	    public interface Actuator {
45	        /**
46	         * Initializes the actuator and returns a list of skills it is capable of performing. This
47	         * method will be invoked only once.
48	         */
49	        List<Skill> onCreate(Context context);
50	
51	        /**
52	         * Called when it is time for the actuator to release any resources it might be holding.
53	         * This method is invoked only once. The object won't be usable after this method returns.
54	         */
55	        void onDestroy();
56	    }
57	
58	    public SkillRouter(Context context) {
59	        for (Actuator actuator : ACTUATORS) {
60	            mSkills.addAll(actuator.onCreate(context));
61	        }
62	    }
63	
64	    /**
65	     * Attempts to process the received text. This is a naive and inefficient NLP processing, used
66	     * for illustration purposes only.
67	     * @param recognizedTexts list of recognized text in confidence level order
68	     */
69	    public void process(List<String> recognizedTexts, TextToSpeech tts) {
70	        for (String recognizedText : recognizedTexts) {
71	            for (Skill skill : mSkills) {
72	                if (skill.tryExecute(recognizedText, tts)) {
73	                    return;
74	                }
75	            }
76	        }
77	        tts.speak(R.string.speech_reply_unrecognized_cmd);
78	    }
79	
80	    /**
81	     * Called to release resources any actuator might be holding
82	     */
83	    public void destroy() {
84	        for (Actuator actuator : ACTUATORS) {
85	            actuator.onDestroy();
86	        }
87	    }
88	}
