17	package com.android.car.voicecontrol.actuators;
18	
19	import android.car.Car;
20	import android.car.VehicleAreaSeat;
21	import android.car.VehicleAreaWheel;
22	import android.car.VehiclePropertyIds;
23	import android.car.hardware.CarPropertyConfig;
24	import android.car.hardware.property.CarPropertyManager;
25	import android.content.Context;
26	
27	import com.android.car.voicecontrol.R;
28	import com.android.car.voicecontrol.TextToSpeech;
29	
30	import java.util.ArrayList;
31	import java.util.Arrays;
32	import java.util.List;
33	
34	/**
35	 * Actuator that interacts with the vehicle properties
36	 */
37	public class CarActuator implements SkillRouter.Actuator {
38	    private Context mContext;
39	    private Car mCar;
40	    private CarPropertyManager mCarPropertyManager;
41	    private float mSpeedConversionFactor;
42	    private String mSpeedUnit;
43	    private float mPressureConversionFactor;
44	    private String mPressureUnit;
45	
46	    /** Area identifier used for sensors corresponding to global VHAL properties */
47	    private static final int GLOBAL_AREA_ID = 0;
48	
49	    private enum Zone {
50	        FRONT(
51	                VehicleAreaWheel.WHEEL_LEFT_FRONT | VehicleAreaWheel.WHEEL_RIGHT_FRONT,
52	                VehicleAreaSeat.SEAT_ROW_1_CENTER | VehicleAreaSeat.SEAT_ROW_1_LEFT
53	                        | VehicleAreaSeat.SEAT_ROW_1_RIGHT
54	        ),
55	        BACK(
56	                VehicleAreaWheel.WHEEL_LEFT_REAR | VehicleAreaWheel.WHEEL_RIGHT_REAR,
57	                VehicleAreaSeat.SEAT_ROW_2_LEFT | VehicleAreaSeat.SEAT_ROW_2_CENTER
58	                | VehicleAreaSeat.SEAT_ROW_2_RIGHT | VehicleAreaSeat.SEAT_ROW_3_LEFT
59	                | VehicleAreaSeat.SEAT_ROW_3_CENTER | VehicleAreaSeat.SEAT_ROW_3_RIGHT
60	        ),
61	        ;
62	        public final int mWheelAreasBitmap;
63	        public final int mSeatAreasBitmap;
64	
65	        Zone(int wheelAreasBitmap, int seatAreasBitmap) {
66	            mWheelAreasBitmap = wheelAreasBitmap;
67	            mSeatAreasBitmap = seatAreasBitmap;
68	        }
69	    }
70	
71	    @Override
72	    public List<Skill> onCreate(Context context) {
73	        mContext = context;
74	        mCar = Car.createCar(context);
75	        mCarPropertyManager = (CarPropertyManager) mCar.getCarManager(Car.PROPERTY_SERVICE);
76	        mSpeedConversionFactor = mContext.getResources()
77	                .getFloat(R.dimen.property_speed_conversion);
78	        mSpeedUnit = mContext.getString(R.string.property_speed_unit);
79	        mPressureConversionFactor = mContext.getResources()
80	                .getFloat(R.dimen.property_pressure_conversion);
81	        mPressureUnit = mContext.getString(R.string.property_pressure_unit);
82	
83	        return Arrays.asList(
84	                new Skill("turn.* ac (on|off)( at the (back|front))?",
85	                        (args, tts) -> changeAC("on".equals(args[1]), tts, args[3])),
86	                new Skill("what.* pressure.* tires",
87	                        (args, tts) -> informTirePressure(tts)),
88	                new Skill("what.* my speed", (args, tts) -> informSpeed(tts))
89	        );
90	    }
91	
92	    @Override
93	    public void onDestroy() {
94	        mCar.disconnect();
95	    }
96	
97	    private boolean changeAC(boolean turnOn, TextToSpeech tts, String zoneName) {
98	        CarPropertyConfig config = mCarPropertyManager
99	                .getCarPropertyConfig(VehiclePropertyIds.HVAC_AC_ON);
100	        if (config == null) {
101	            tts.speak(R.string.speech_reply_cannot_control_ac);
102	            return true;
103	        }
104	
105	        // If zone is not provided, we assume it is the front seats.
106	        Zone zone = zoneName != null ? Zone.valueOf(zoneName.toUpperCase()) : Zone.FRONT;
107	        List<Integer> areasToChange = new ArrayList<>();
108	        for (int areaId : config.getAreaIds()) {
109	            if ((areaId & zone.mSeatAreasBitmap) == 0) {
110	                continue;
111	            }
112	            // Check which areas we need to actually change
113	            boolean isACInAreaOn = mCarPropertyManager
114	                    .getBooleanProperty(VehiclePropertyIds.HVAC_AC_ON, areaId);
115	            if (isACInAreaOn != turnOn) {
116	                areasToChange.add(areaId);
117	            }
118	        }
119	        if (areasToChange.isEmpty()) {
120	            tts.speak(turnOn ? R.string.speech_reply_ac_is_already_on
121	                    : R.string.speech_reply_ac_is_already_off);
122	            return true;
123	        }
124	
125	        for (int areaId : areasToChange) {
126	            mCarPropertyManager.setBooleanProperty(VehiclePropertyIds.HVAC_AC_ON, areaId, turnOn);
127	        }
128	        tts.speak(turnOn ? R.string.speech_reply_turning_ac_on
129	                : R.string.speech_reply_turning_ac_off);
130	        return false;
131	    }
132	
133	    private boolean informSpeed(TextToSpeech tts) {
134	        if (!mCarPropertyManager.isPropertyAvailable(VehiclePropertyIds.PERF_VEHICLE_SPEED,
135	                GLOBAL_AREA_ID)) {
136	            tts.speak(R.string.speech_reply_cannot_read_speed);
137	            return true;
138	        }
139	        float speedInMetersPerSecond = mCarPropertyManager.getFloatProperty(
140	                VehiclePropertyIds.PERF_VEHICLE_SPEED, GLOBAL_AREA_ID);
141	        int speedInUserUnit = (int) (speedInMetersPerSecond * mSpeedConversionFactor);
142	        tts.speak(R.string.speech_reply_speed_value, speedInUserUnit, mSpeedUnit);
143	        return true;
144	    }
145	
146	    private boolean informTirePressure(TextToSpeech tts) {
147	        CarPropertyConfig config = mCarPropertyManager
148	                .getCarPropertyConfig(VehiclePropertyIds.TIRE_PRESSURE);
149	        if (config == null) {
150	            tts.speak(R.string.speech_reply_cannot_read_tire_pressure);
151	            return true;
152	        }
153	
154	        // Retrieve areas this property is available on, and classify them by front and rear.
155	        List<Integer> frontTirePressure = new ArrayList<>();
156	        List<Integer> rearTirePressure = new ArrayList<>();
157	        for (int areaId : config.getAreaIds()) {
158	            float pressureKPA = mCarPropertyManager.getFloatProperty(
159	                    VehiclePropertyIds.TIRE_PRESSURE, areaId);
160	            int pressureUserUnit = (int) (pressureKPA * mPressureConversionFactor);
161	            if ((areaId & Zone.FRONT.mWheelAreasBitmap) != 0) {
162	                frontTirePressure.add(pressureUserUnit);
163	            } else {
164	                rearTirePressure.add(pressureUserUnit);
165	            }
166	        }
167	
168	        // This simplified logic assumes there are values for both front and rear.
169	        tts.speak(R.string.speech_reply_tire_pressure_value, integerListToString(frontTirePressure),
170	                mPressureUnit, integerListToString(rearTirePressure), mPressureUnit);
171	        return true;
172	    }
173	
174	    private String integerListToString(List<Integer> values) {
175	        StringBuilder sb = new StringBuilder();
176	        for (int i = 0; i < values.size(); i++) {
177	            if (i > 0 && i < (values.size() - 1)) {
178	                sb.append(mContext.getString(R.string.speech_reply_tire_pressure_separator));
179	            } else if (i == (values.size() - 1)) {
180	                sb.append(mContext.getString(R.string.speech_reply_tire_pressure_last_separator));
181	            }
182	            sb.append(values.get(i));
183	        }
184	        return sb.toString();
185	    }
186	}
