17	package com.android.car.voicecontrol.runtime;
18	import java.util.Locale;
19	public final class VoiceCommandRouter {
20	    public VoiceRoute route(VoiceCommand command){
21	        String value=(command.action+" "+command.utterance).toLowerCase(Locale.ROOT);
22	        if(value.contains("call")||value.contains("phone"))return new VoiceRoute(VoiceRoute.Domain.PHONE,"dial");
23	        if(value.contains("message")||value.contains("sms"))return new VoiceRoute(VoiceRoute.Domain.MESSAGE,"compose");
24	        if(value.contains("music")||value.contains("play"))return new VoiceRoute(VoiceRoute.Domain.MEDIA,"play");
25	        if(value.contains("navigate")||value.contains("route"))return new VoiceRoute(VoiceRoute.Domain.NAVIGATION,"navigate");
26	        if(value.contains("climate")||value.contains("temperature"))return new VoiceRoute(VoiceRoute.Domain.VEHICLE,"comfort");
27	        return new VoiceRoute(VoiceRoute.Domain.UNKNOWN,"delegate");
28	    }
29	}
