162	            int supportedAudioRouteMask = getSupportedAudioRouteMask();
163	
164	            if ((supportedAudioRouteMask & CallAudioState.ROUTE_EARPIECE) != 0) {
165	                audioRouteList.add(CallAudioState.ROUTE_EARPIECE);
166	            } else if ((supportedAudioRouteMask & CallAudioState.ROUTE_WIRED_HEADSET) != 0) {
167	                audioRouteList.add(CallAudioState.ROUTE_WIRED_HEADSET);
168	            }
169	            if ((supportedAudioRouteMask & CallAudioState.ROUTE_BLUETOOTH) != 0) {
170	                audioRouteList.add(CallAudioState.ROUTE_BLUETOOTH);
171	            }
172	            if ((supportedAudioRouteMask & CallAudioState.ROUTE_SPEAKER) != 0) {
173	                audioRouteList.add(CallAudioState.ROUTE_SPEAKER);
