254	    public boolean placeSms(Activity activity, String number, String name, String uid) {
255	        BluetoothDevice device = mCurrentHfpDeviceLiveData.getValue();
256	
257	        Bundle bundle = new Bundle();
258	        bundle.putString(CarVoiceInteractionSession.KEY_ACTION, VOICE_ACTION_SEND_SMS);
259	        bundle.putString(CarVoiceInteractionSession.KEY_PHONE_NUMBER, number);
260	        bundle.putString(CarVoiceInteractionSession.KEY_RECIPIENT_NAME, name);
261	        bundle.putString(CarVoiceInteractionSession.KEY_RECIPIENT_UID, uid);
262	        bundle.putString(CarVoiceInteractionSession.KEY_DEVICE_ADDRESS, device.getAddress());
263	        bundle.putString(CarVoiceInteractionSession.KEY_DEVICE_NAME, device.getName());
264	
265	        Context context = activity.getApplicationContext();
266	        Intent intent = new Intent(context, MessagingService.class)
267	                .setAction(ACTION_DIRECT_SEND)
268	                .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP)
269	                .setClass(context, MessagingService.class);
270	
271	        int requestCode = ACTION_DIRECT_SEND.hashCode();
272	        PendingIntent pendingIntent = PendingIntent.getForegroundService(
273	                context, requestCode, intent,
274	                PendingIntent.FLAG_ONE_SHOT | PendingIntent.FLAG_IMMUTABLE);
275	
276	        bundle.putParcelable(KEY_SEND_PENDING_INTENT, pendingIntent);
277	        activity.showAssist(bundle);
278	
279	        return true;
280	    }
